import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'1WM5CLqoLFN2yEUguuVY',titulo:'TESTO ESSENCIAL - Fórmula Exclusiva com Feno Grego + Boro + Arginina + ZMA + Vitamina B6 - Precursor da Testosterona - 60 cápsulas',listing:'MLB5761677016'},{id:'2bvf1eThLNTx4TSWmm6j',titulo:'Cpu Monitor Dell Optiplex Core I5 4570 8gb 240gb Ssd Win 11',listing:'MLB5363320228'}];
test('triagem49 preserva campos operacionais, recusa outra identidade e é idempotente',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'},{id:'outro'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('TESTO não endossa alegação hormonal nem prescreve dose ou irregularidade',()=>{const x=correctProductData(rows[0]);assert.match(x.titulo,/alegação.*não verificada/);assert.match(x.comentario,/não são confirmados nem prescritos/);assert.match(x.comentario,/não concluímos que seja irregular/);assert.doesNotMatch(x.pros,/precursor|aumenta|libido|eficácia|sem glúten|2 cápsulas/i);});
test('Dell distingue Windows anunciado de suporte sem inventar série, licença ou TPM',()=>{const x=correctProductData(rows[1]);assert.equal(x.titulo,rows[1].titulo);assert.match(x.comentario,/não comprova, por si só/);assert.match(x.comentario,/Não verificamos TPM/);assert.doesNotMatch(x.pros,/compatível|suportado|licenciado|3020|7010|fps|jogos/i);});
test('Nike permanece sem correção específica nesta passagem',()=>{const p={id:'2CwDkIClWXzNIUFxZVVo',titulo:'Tênis Nike Flex Experience Run 12 Masculino',comentario:'Texto local preservado',linkAfiliado:'https://meli.la/preservado'},x=correctProductData(p);for(const k of Object.keys(p))assert.equal(x[k],p[k]);assert.equal(x.pros,'');assert.equal(x.contras,'');});
